# 自定义异常
class ValidationError(Exception):
    def __init__(self, message):
        self.message = message
        super().__init__(self.message)

try:
    raise ValidationError("数据验证失败")
except ValidationError as e:
    print(f"捕获自定义异常: {e.message}")
